use crate::{Connection, Result};
use std::ops::Deref;

/// Options for how a Transaction should behave when it is dropped.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub enum DropBehavior {
    /// Roll back the changes. This is the default.
    Rollback,

    /// Commit the changes.
    Commit,

    /// Do not commit or roll back changes - this will leave the transaction open, so should be used with care.
    Ignore,

    /// Panic. Used to enforce intentional behavior during development.
    Panic,
}

/// Represents a transaction on a database connection.
///
/// ## Note
///
/// Transactions will roll back by default. Use `commit` method to explicitly
/// commit the transaction, or use `set_drop_behavior` to change what happens
/// when the transaction is dropped.
///
/// ## Example
///
/// ```rust,no_run
/// # use duckdb::{Connection, Result};
/// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
/// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
/// fn perform_queries(conn: &mut Connection) -> Result<()> {
///     let tx = conn.transaction()?;
///
///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
///
///     tx.commit()
/// }
/// ```
#[derive(Debug)]
pub struct Transaction<'conn> {
    conn: &'conn Connection,
    drop_behavior: DropBehavior,
}

impl Transaction<'_> {
    /// Begin a new transaction. Cannot be nested.
    ///
    /// Even though we don't mutate the connection, we take a `&mut Connection`
    /// so as to prevent nested transactions on the same connection. For cases
    /// where this is unacceptable, [`Transaction::new_unchecked`] is available.
    #[inline]
    pub fn new(conn: &mut Connection) -> Result<Transaction<'_>> {
        Self::new_unchecked(conn)
    }

    /// Begin a new transaction, failing if a transaction is open.
    ///
    /// If a transaction is already open, this will return an error. Where
    /// possible, [`Transaction::new`] should be preferred, as it provides a
    /// compile-time guarantee that transactions are not nested.
    #[inline]
    pub fn new_unchecked(conn: &Connection) -> Result<Transaction<'_>> {
        let query = "BEGIN TRANSACTION";
        conn.execute_batch(query).map(move |_| Transaction {
            conn,
            drop_behavior: DropBehavior::Rollback,
        })
    }

    /// Get the current setting for what happens to the transaction when it is
    /// dropped.
    #[inline]
    pub fn drop_behavior(&self) -> DropBehavior {
        self.drop_behavior
    }

    /// Configure the transaction to perform the specified action when it is
    /// dropped.
    #[inline]
    pub fn set_drop_behavior(&mut self, drop_behavior: DropBehavior) {
        self.drop_behavior = drop_behavior
    }

    /// A convenience method which consumes and commits a transaction.
    #[inline]
    pub fn commit(mut self) -> Result<()> {
        self.commit_()
    }

    #[inline]
    fn commit_(&mut self) -> Result<()> {
        self.conn.execute_batch("COMMIT")
    }

    /// A convenience method which consumes and rolls back a transaction.
    #[inline]
    pub fn rollback(mut self) -> Result<()> {
        self.rollback_()
    }

    #[inline]
    fn rollback_(&mut self) -> Result<()> {
        self.conn.execute_batch("ROLLBACK")
    }

    /// Consumes the transaction, committing or rolling back according to the
    /// current setting (see `drop_behavior`).
    ///
    /// Functionally equivalent to the `Drop` implementation, but allows
    /// callers to see any errors that occur.
    #[inline]
    pub fn finish(mut self) -> Result<()> {
        self.finish_()
    }

    #[inline]
    fn finish_(&mut self) -> Result<()> {
        // if self.conn.is_autocommit() {
        //     println!("is autocommit");
        //     return Ok(());
        // }
        match self.drop_behavior() {
            DropBehavior::Commit => self.commit_().or_else(|_| self.rollback_()),
            DropBehavior::Rollback => self.rollback_(),
            DropBehavior::Ignore => Ok(()),
            DropBehavior::Panic => panic!("Transaction dropped unexpectedly."),
        }
    }
}

impl Deref for Transaction<'_> {
    type Target = Connection;

    #[inline]
    fn deref(&self) -> &Connection {
        self.conn
    }
}

impl Drop for Transaction<'_> {
    #[inline]
    fn drop(&mut self) {
        let _ = self.finish_();
    }
}

impl Connection {
    /// Begin a new transaction with the default behavior (DEFERRED).
    ///
    /// The transaction defaults to rolling back when it is dropped. If you
    /// want the transaction to commit, you must call
    /// [`commit`](Transaction::commit) or [`set_drop_behavior(DropBehavior:
    /// :Commit)`](Transaction::set_drop_behavior).
    ///
    /// ## Example
    ///
    /// ```rust,no_run
    /// # use duckdb::{Connection, Result};
    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
    /// fn perform_queries(conn: &mut Connection) -> Result<()> {
    ///     let tx = conn.transaction()?;
    ///
    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
    ///
    ///     tx.commit()
    /// }
    /// ```
    ///
    /// # Failure
    ///
    /// Will return `Err` if the underlying DuckDB call fails.
    #[inline]
    pub fn transaction(&mut self) -> Result<Transaction<'_>> {
        Transaction::new(self)
    }

    /// Begin a new transaction with the default behavior (DEFERRED).
    ///
    /// Attempt to open a nested transaction will result in a DuckDB error.
    /// `Connection::transaction` prevents this at compile time by taking `&mut
    /// self`, but `Connection::unchecked_transaction()` may be used to defer
    /// the checking until runtime.
    ///
    /// See [`Connection::transaction`] and [`Transaction::new_unchecked`]
    /// (which can be used if the default transaction behavior is undesirable).
    ///
    /// ## Example
    ///
    /// ```rust,no_run
    /// # use duckdb::{Connection, Result};
    /// # use std::rc::Rc;
    /// # fn do_queries_part_1(_conn: &Connection) -> Result<()> { Ok(()) }
    /// # fn do_queries_part_2(_conn: &Connection) -> Result<()> { Ok(()) }
    /// fn perform_queries(conn: Rc<Connection>) -> Result<()> {
    ///     let tx = conn.unchecked_transaction()?;
    ///
    ///     do_queries_part_1(&tx)?; // tx causes rollback if this fails
    ///     do_queries_part_2(&tx)?; // tx causes rollback if this fails
    ///
    ///     tx.commit()
    /// }
    /// ```
    ///
    /// # Failure
    ///
    /// Will return `Err` if the underlying DuckDB call fails. The specific
    /// error returned if transactions are nested is currently unspecified.
    pub fn unchecked_transaction(&self) -> Result<Transaction<'_>> {
        Transaction::new_unchecked(self)
    }
}

#[cfg(test)]
mod test {
    use super::DropBehavior;
    use crate::{Connection, Result};

    fn checked_no_autocommit_memory_handle() -> Result<Connection> {
        let db = Connection::open_in_memory()?;
        db.execute_batch(
            r"
            CREATE TABLE foo (x INTEGER);
            -- SET AUTOCOMMIT TO OFF;
        ",
        )?;
        Ok(db)
    }

    #[test]
    fn test_drop() -> Result<()> {
        let mut db = checked_no_autocommit_memory_handle()?;
        {
            let tx = db.transaction()?;
            assert!(tx.execute_batch("INSERT INTO foo VALUES(1)").is_ok());
            // default: rollback
        }
        {
            let mut tx = db.transaction()?;
            tx.execute_batch("INSERT INTO foo VALUES(2)")?;
            tx.set_drop_behavior(DropBehavior::Commit);
        }
        {
            let tx = db.transaction()?;
            assert_eq!(
                2i32,
                tx.query_row::<i32, _, _>("SELECT SUM(x) FROM foo", [], |r| r.get(0))?
            );
        }
        Ok(())
    }

    #[test]
    fn test_unchecked_nesting() -> Result<()> {
        let db = checked_no_autocommit_memory_handle()?;

        {
            db.unchecked_transaction()?;
            // default: rollback
        }
        {
            let tx = db.unchecked_transaction()?;
            tx.execute_batch("INSERT INTO foo VALUES(1)")?;
            // Ensure this doesn't interfere with ongoing transaction
            // let e = tx.unchecked_transaction().unwrap_err();
            // assert_nested_tx_error(e);
            tx.execute_batch("INSERT INTO foo VALUES(1)")?;
            tx.commit()?;
        }

        assert_eq!(
            2i32,
            db.query_row::<i32, _, _>("SELECT SUM(x) FROM foo", [], |r| r.get(0))?
        );
        Ok(())
    }

    #[test]
    fn test_explicit_rollback_commit() -> Result<()> {
        let mut db = checked_no_autocommit_memory_handle()?;
        {
            let tx = db.transaction()?;
            tx.execute_batch("INSERT INTO foo VALUES(1)")?;
            tx.rollback()?;
        }
        {
            let tx = db.transaction()?;
            tx.execute_batch("INSERT INTO foo VALUES(4)")?;
            tx.commit()?;
        }
        {
            let tx = db.transaction()?;
            assert_eq!(
                4i32,
                tx.query_row::<i32, _, _>("SELECT SUM(x) FROM foo", [], |r| r.get(0))?
            );
        }
        Ok(())
    }

    #[test]
    fn test_rc() -> Result<()> {
        use std::rc::Rc;
        let mut conn = Connection::open_in_memory()?;
        let rc_txn = Rc::new(conn.transaction()?);

        // This will compile only if Transaction is Debug
        Rc::try_unwrap(rc_txn).unwrap();
        Ok(())
    }
}

use super::{DecimalSignature, DecimalValue, MAX_DECIMAL_WIDTH};
use crate::{
    Result,
    connection::FFILink,
    data_chunk::VectorCollection,
    error::Error,
    logical_type::{LogicalType, LogicalTypeID},
    types::{FromValue, ToValue},
    value::Value,
    vector::{Vector, VectorElement, WritableVectorElement},
};

/// Widest `DECIMAL` whose values all fit `rust_decimal`'s 96-bit mantissa.
const MAX_RUST_DECIMAL_WIDTH: u8 = 28;

/// Uses the widest `DECIMAL`, which holds any `rust_decimal::Decimal`.
impl From<rust_decimal::Decimal> for DecimalValue {
    fn from(value: rust_decimal::Decimal) -> Self {
        Self {
            value: value.mantissa(),
            width: MAX_DECIMAL_WIDTH,
            scale: value.scale() as u8,
        }
    }
}

/// Fails when the value or scale exceeds `rust_decimal`'s 96-bit mantissa or scale limit of 28.
impl TryFrom<DecimalValue> for rust_decimal::Decimal {
    type Error = rust_decimal::Error;

    fn try_from(value: DecimalValue) -> std::result::Result<Self, Self::Error> {
        Self::try_from_i128_with_scale(value.value, u32::from(value.scale))
    }
}

impl ToValue for rust_decimal::Decimal {
    fn value<C: FFILink + ?Sized>(&self, link: &C) -> Result<Value> {
        DecimalValue::from(*self).value(link)
    }
}

impl FromValue for rust_decimal::Decimal {
    fn _get_inner(value: &Value) -> Result<Self> {
        let decimal = DecimalValue::_get_inner(value)?;
        rust_decimal::Decimal::try_from(decimal).map_err(|err| Error::invalid_input(format!("{decimal:?}: {err}")))
    }
}

fn signature<U: VectorElement>(vector: &Vector<'_, U>) -> DecimalSignature {
    vector
        .decimal_signature()
        .expect("validated DECIMAL vector has a signature")
}

/// Reads and writes `DECIMAL` columns of width up to 28, which always fit.
impl VectorElement for rust_decimal::Decimal {
    const TYPE_ID: LogicalTypeID = LogicalTypeID::DUCKDB_V2_LOGICAL_TYPE_ID_DECIMAL;

    // The storage integer depends on the column's width.
    type Internal = ();

    type Ref<'a> = rust_decimal::Decimal;

    fn validate(other: &LogicalType, _children: Option<&VectorCollection>) -> Result<bool> {
        if other.type_id() != Self::TYPE_ID {
            return Ok(false);
        }
        Ok(DecimalSignature::from_logical_type(other)?.width <= MAX_RUST_DECIMAL_WIDTH)
    }

    unsafe fn get<'a, U: VectorElement>(vector: &'a Vector<'_, U>, physical: usize, _logical: usize) -> Self::Ref<'a>
    where
        Self: 'a,
    {
        let DecimalSignature { width, scale } = signature(vector);
        let data = vector.view.as_ref().unwrap().as_ptr() as *const u8;
        let value = unsafe {
            match width {
                1..=4 => i128::from(*(data as *const i16).add(physical)),
                5..=9 => i128::from(*(data as *const i32).add(physical)),
                10..=18 => i128::from(*(data as *const i64).add(physical)),
                _ => *(data as *const i128).add(physical),
            }
        };
        rust_decimal::Decimal::from_i128_with_scale(value, u32::from(scale))
    }
}

/// Rescales to the column's scale; fails instead of rounding or overflowing.
impl WritableVectorElement for rust_decimal::Decimal {
    type Write<'a> = rust_decimal::Decimal;

    unsafe fn write(vector: &mut Vector<'_, Self>, index: usize, value: Option<Self::Write<'_>>) -> Result<()> {
        let Some(value) = value else {
            return vector.write_raw::<()>(index, None);
        };
        let DecimalSignature { width, scale } = signature(vector);
        let from_scale = value.scale();
        let to_scale = u32::from(scale);
        let scaled = if from_scale <= to_scale {
            10i128
                .checked_pow(to_scale - from_scale)
                .and_then(|factor| value.mantissa().checked_mul(factor))
        } else {
            let factor = 10i128.pow(from_scale - to_scale);
            (value.mantissa() % factor == 0).then(|| value.mantissa() / factor)
        };
        let decimal = DecimalValue {
            value: scaled
                .ok_or_else(|| Error::invalid_input(format!("{value} does not fit DECIMAL({width}, {scale})")))?,
            width,
            scale,
        };
        decimal.check()?;
        match width {
            1..=4 => vector.write_raw(index, decimal.to_primitive::<i16>()),
            5..=9 => vector.write_raw(index, decimal.to_primitive::<i32>()),
            10..=18 => vector.write_raw(index, decimal.to_primitive::<i64>()),
            _ => vector.write_raw(index, Some(decimal.value)),
        }
    }
}

#[cfg(test)]
mod tests {
    use std::str::FromStr;

    use super::*;
    use crate::{
        Parameters,
        data_chunk::DataChunk,
        environment::{Environment, StorageLocation},
        types::DuckDBType,
    };

    fn dec(text: &str) -> rust_decimal::Decimal {
        rust_decimal::Decimal::from_str(text).unwrap()
    }

    #[test]
    fn rust_decimal_value_round_trips() -> Result<()> {
        let env = Environment::new()?;
        let db = env.open(StorageLocation::InMemory)?;
        let conn = db.connect()?;

        for text in [
            "123.45",
            "-0.001",
            "0",
            "79228162514264337593543950335",
            "0.0000000000000000000000000001",
        ] {
            let decimal = dec(text);
            let raw = DecimalValue::from(decimal);
            assert_eq!(raw.width, 38);
            assert_eq!(rust_decimal::Decimal::try_from(raw), Ok(decimal));

            let value = decimal.value(&conn)?;
            assert_eq!(value.get::<rust_decimal::Decimal>()?, Some(decimal));

            let mut result = conn.query("SELECT $1::VARCHAR", Parameters::positional(&[&decimal]))?;
            let chunk = result.next_chunk()?.expect("query returned no rows");
            let text_vector = chunk.get_vector_at::<String>(0)?;
            assert_eq!(text_vector.get(0)?.map(|s| s.to_string()), Some(text.to_string()));
        }

        Ok(())
    }

    #[test]
    fn rust_decimal_conversion_reports_overflow() -> Result<()> {
        let too_wide = DecimalValue::new(10i128.pow(37), 38, 0);
        assert!(rust_decimal::Decimal::try_from(too_wide).is_err());

        let too_precise = DecimalValue::new(1i16, 30, 29);
        assert!(rust_decimal::Decimal::try_from(too_precise).is_err());

        let env = Environment::new()?;
        let db = env.open(StorageLocation::InMemory)?;
        let conn = db.connect()?;
        let value = too_wide.value(&conn)?;
        assert!(value.get::<rust_decimal::Decimal>().is_err());

        Ok(())
    }

    #[test]
    fn rust_decimal_vector_reads_every_storage_width() -> Result<()> {
        let env = Environment::new()?;
        let db = env.open(StorageLocation::InMemory)?;
        let conn = db.connect()?;

        let mut result = conn.query(
            "SELECT -1.5::DECIMAL(4, 1), 123.45::DECIMAL(5, 2), 1.5::DECIMAL(18, 1), \
                 -9999999999999999999999999.999::DECIMAL(28, 3), NULL::DECIMAL(9, 2), 1::DECIMAL(29, 0), \
                 MAP {1: 1.21::DECIMAL(4, 2)}",
            Parameters::None,
        )?;
        let chunk = result.next_chunk()?.expect("query returned no rows");

        assert_eq!(
            chunk.get_vector_at::<rust_decimal::Decimal>(0)?.get(0)?,
            Some(dec("-1.5"))
        );
        assert_eq!(
            chunk.get_vector_at::<rust_decimal::Decimal>(1)?.get(0)?,
            Some(dec("123.45"))
        );
        assert_eq!(
            chunk.get_vector_at::<rust_decimal::Decimal>(2)?.get(0)?,
            Some(dec("1.5"))
        );
        assert_eq!(
            chunk.get_vector_at::<rust_decimal::Decimal>(3)?.get(0)?,
            Some(dec("-9999999999999999999999999.999"))
        );
        assert_eq!(chunk.get_vector_at::<rust_decimal::Decimal>(4)?.get(0)?, None);
        assert!(chunk.get_vector_at::<rust_decimal::Decimal>(5).is_err());

        let map = chunk.get_vector_at::<crate::types::Map<i32, rust_decimal::Decimal>>(6)?;
        assert_eq!(map.get(0)?.unwrap().get(&1)?, Some(dec("1.21")));

        Ok(())
    }

    #[test]
    fn rust_decimal_vector_writes_rescale() -> Result<()> {
        let env = Environment::new()?;
        let db = env.open(StorageLocation::InMemory)?;
        let conn = db.connect()?;

        for width in [4, 9, 18, 28] {
            let logical_type = DecimalSignature { width, scale: 2 }.logical_type(&conn)?;
            let mut chunk = DataChunk::create(&[logical_type], true)?;
            let mut vector = chunk.get_vector_at_mut::<rust_decimal::Decimal>(0)?;
            vector.set_size(4)?;
            vector.write(0, Some(dec("1.5")))?;
            vector.write(1, Some(dec("-12.300")))?;
            vector.write(2, None)?;
            vector.write(3, Some(dec("99.99")))?;
            assert_eq!(
                vector.iter()?.collect::<Vec<_>>(),
                vec![Some(dec("1.50")), Some(dec("-12.30")), None, Some(dec("99.99"))]
            );

            assert!(vector.write(0, Some(dec("1.234"))).is_err());
            let too_big = 10i128.pow(u32::from(width) - 2);
            assert!(
                vector
                    .write(0, Some(rust_decimal::Decimal::from_i128_with_scale(too_big, 0)))
                    .is_err()
            );
        }

        let chunk = DataChunk::create(&[crate::types::Decimal::<38, 2>::logical_type(&conn)?], true)?;
        assert!(chunk.get_vector_at::<rust_decimal::Decimal>(0).is_err());

        Ok(())
    }
}

use std::{
    error, fmt,
    hash::{Hash, Hasher},
};

use crate::{
    Result, ToSql, ffi,
    types::{FromSql, FromSqlError, FromSqlResult, ToSqlOutput, Value, ValueRef},
};

use super::{TimeUnit, to_duckdb_hugeint};

#[cfg(feature = "rust_decimal")]
use rust_decimal::prelude::FromPrimitive as _;

/// A DuckDB `DECIMAL(width, scale)` value.
///
/// `value` stores the scaled integer payload. For example,
/// `123.45::DECIMAL(9, 2)` is represented as
/// `Decimal::new(9, 2, 12345)?`.
///
/// The declared width is preserved when reading and writing DuckDB `DECIMAL`
/// columns. Values converted from non-decimal sources, such as integers or
/// `rust_decimal` values, infer the smallest width that can represent the
/// scaled payload. Width is not part of equality or hashing: values with the
/// same `scale` and scaled integer payload compare equal even if they arrived
/// through paths with different declared widths. Use [`Decimal::width`] when
/// the declared width matters; `Eq` and `Hash` do not preserve it.
///
/// Scale is part of identity: `DECIMAL(2, 1)` with payload `12` and
/// `DECIMAL(3, 2)` with payload `120` compare different. `Decimal`
/// intentionally does not implement `Ord` or `PartialOrd`; sort in SQL or
/// compare an explicitly normalized representation when ordering is needed.
#[derive(Copy, Clone, Debug)]
pub struct Decimal {
    width: u8,
    scale: u8,
    value: i128,
}

impl PartialEq for Decimal {
    fn eq(&self, other: &Self) -> bool {
        self.scale == other.scale && self.value == other.value
    }
}

impl Eq for Decimal {}

impl Hash for Decimal {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.scale.hash(state);
        self.value.hash(state);
    }
}

impl fmt::Display for Decimal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let scale = usize::from(self.scale);
        let raw = self.value.unsigned_abs().to_string();

        if scale == 0 {
            return f.pad_integral(!self.value.is_negative(), "", &raw);
        }

        let mut magnitude = String::new();
        if raw.len() <= scale {
            magnitude.push_str("0.");
            for _ in 0..(scale - raw.len()) {
                magnitude.push('0');
            }
            magnitude.push_str(&raw);
        } else {
            let point = raw.len() - scale;
            magnitude.push_str(&raw[..point]);
            magnitude.push('.');
            magnitude.push_str(&raw[point..]);
        }

        f.pad_integral(!self.value.is_negative(), "", &magnitude)
    }
}

impl Decimal {
    /// DuckDB's maximum `DECIMAL` width.
    pub const MAX_WIDTH: u8 = 38;

    /// Builds a valid `DECIMAL(width, scale)` wrapper.
    ///
    /// Returns [`DecimalError`] when `width` is outside DuckDB's `1..=38`
    /// range, `scale` is larger than `width`, or `value` has more digits than
    /// `width` allows.
    pub fn new(width: u8, scale: u8, value: i128) -> std::result::Result<Self, DecimalError> {
        if width == 0 || width > Self::MAX_WIDTH {
            return Err(DecimalError::InvalidWidth {
                width,
                max: Self::MAX_WIDTH,
            });
        }
        if scale > width {
            return Err(DecimalError::ScaleExceedsWidth { scale, width });
        }
        let digits = decimal_digits(value);
        if digits > width {
            return Err(DecimalError::ValueExceedsWidth { digits, width });
        }
        Ok(Self { width, scale, value })
    }

    pub(crate) fn validate_signed_scale(width: u8, scale: i8) -> std::result::Result<u8, String> {
        let scale = u8::try_from(scale).map_err(|_| format!("negative decimal scale is not supported: {scale}"))?;
        Self::new(width, scale, 0).map_err(|err| err.to_string())?;
        Ok(scale)
    }

    /// Builds a decimal value from trusted DuckDB output.
    ///
    /// The caller must ensure `width`, `scale`, and `value` are a valid DuckDB
    /// decimal triple.
    pub(crate) fn from_chunk(width: u8, scale: u8, value: i128) -> Self {
        debug_assert!(
            Self::new(width, scale, value).is_ok(),
            "DuckDB produced an invalid decimal triple"
        );
        Self { width, scale, value }
    }

    /// Returns the declared precision for DuckDB `DECIMAL` values.
    ///
    /// Values converted from non-decimal sources infer the smallest width that
    /// can represent the scaled payload.
    #[inline]
    pub const fn width(self) -> u8 {
        self.width
    }

    /// Returns the number of fractional digits.
    #[inline]
    pub const fn scale(self) -> u8 {
        self.scale
    }

    /// Returns the scaled integer payload.
    #[inline]
    pub const fn value(self) -> i128 {
        self.value
    }
}

/// Error returned when constructing an invalid [`Decimal`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecimalError {
    /// The width is outside DuckDB's supported range.
    InvalidWidth {
        /// The requested width.
        width: u8,
        /// DuckDB's maximum decimal width.
        max: u8,
    },
    /// The scale is larger than the width.
    ScaleExceedsWidth {
        /// The requested scale.
        scale: u8,
        /// The requested width.
        width: u8,
    },
    /// The scaled integer payload has more digits than the width allows.
    ValueExceedsWidth {
        /// Number of digits in the payload.
        digits: u8,
        /// The requested width.
        width: u8,
    },
}

impl fmt::Display for DecimalError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match *self {
            Self::InvalidWidth { width, max } => {
                write!(f, "decimal width {width} is outside DuckDB's 1..={max} range")
            }
            Self::ScaleExceedsWidth { scale, width } => {
                write!(f, "decimal scale {scale} exceeds width {width}")
            }
            Self::ValueExceedsWidth { digits, width } => {
                write!(f, "decimal value has {digits} digits, exceeding width {width}")
            }
        }
    }
}

impl error::Error for DecimalError {}

impl From<DecimalError> for crate::Error {
    fn from(err: DecimalError) -> Self {
        Self::ToSqlConversionFailure(err.into())
    }
}

pub(crate) fn to_duckdb_decimal(decimal: Decimal) -> ffi::duckdb_decimal {
    ffi::duckdb_decimal {
        width: decimal.width,
        scale: decimal.scale,
        value: to_duckdb_hugeint(decimal.value),
    }
}

fn decimal_digits_unsigned(value: u128) -> u8 {
    value.checked_ilog10().map_or(1, |digits| digits as u8 + 1)
}

fn decimal_digits(value: i128) -> u8 {
    decimal_digits_unsigned(value.unsigned_abs())
}

fn integer_decimal(value: i128) -> FromSqlResult<Decimal> {
    let digits = decimal_digits(value);
    if digits > Decimal::MAX_WIDTH {
        return Err(FromSqlError::OutOfRange(value));
    }
    Ok(Decimal::from_chunk(digits, 0, value))
}

fn unsigned_integer_decimal(value: u128) -> FromSqlResult<Decimal> {
    let digits = decimal_digits_unsigned(value);
    if digits > Decimal::MAX_WIDTH {
        return Err(FromSqlError::OutOfRangeUnsigned(value));
    }
    Ok(Decimal::from_chunk(digits, 0, value as i128))
}

impl ToSql for Decimal {
    fn to_sql(&self) -> Result<ToSqlOutput<'_>> {
        Ok(ToSqlOutput::Owned(Value::Decimal(*self)))
    }
}

impl FromSql for Decimal {
    fn column_result(value: ValueRef<'_>) -> FromSqlResult<Self> {
        match value {
            ValueRef::Decimal(decimal) => Ok(decimal),
            ValueRef::TinyInt(i) => integer_decimal(i as i128),
            ValueRef::SmallInt(i) => integer_decimal(i as i128),
            ValueRef::Int(i) => integer_decimal(i as i128),
            ValueRef::BigInt(i) => integer_decimal(i as i128),
            ValueRef::HugeInt(i) => integer_decimal(i),
            ValueRef::UHugeInt(i) => unsigned_integer_decimal(i),
            ValueRef::UTinyInt(i) => integer_decimal(i as i128),
            ValueRef::USmallInt(i) => integer_decimal(i as i128),
            ValueRef::UInt(i) => integer_decimal(i as i128),
            ValueRef::UBigInt(i) => integer_decimal(i as i128),
            ValueRef::Timestamp(_, i) => integer_decimal(i as i128),
            ValueRef::Date32(i) => integer_decimal(i as i128),
            ValueRef::Time64(TimeUnit::Microsecond, i) => integer_decimal(i as i128),
            _ => Err(FromSqlError::InvalidType),
        }
    }
}

#[cfg(feature = "rust_decimal")]
impl From<rust_decimal::Decimal> for Decimal {
    fn from(decimal: rust_decimal::Decimal) -> Self {
        let scale = decimal.scale() as u8;
        let mantissa = decimal.mantissa();
        let width = decimal_digits(mantissa).max(scale);

        // rust_decimal's scale is <= 28 and its mantissa fits in 96 bits, so
        // every valid rust_decimal value fits DuckDB's DECIMAL(38, scale).
        Self::new(width, scale, mantissa).expect("rust_decimal values fit DuckDB DECIMAL")
    }
}

#[cfg(feature = "rust_decimal")]
impl TryFrom<Decimal> for rust_decimal::Decimal {
    type Error = rust_decimal::Error;

    fn try_from(decimal: Decimal) -> std::result::Result<Self, Self::Error> {
        Self::try_from_i128_with_scale(decimal.value(), u32::from(decimal.scale()))
    }
}

#[cfg(feature = "rust_decimal")]
impl ToSql for rust_decimal::Decimal {
    fn to_sql(&self) -> Result<ToSqlOutput<'_>> {
        Ok(ToSqlOutput::Owned(Value::Decimal((*self).into())))
    }
}

#[cfg(feature = "rust_decimal")]
fn invalid_decimal_float(kind: &str, value: impl std::fmt::Debug) -> FromSqlError {
    FromSqlError::Other(Box::new(std::io::Error::new(
        std::io::ErrorKind::InvalidData,
        format!("{kind} value {value:?} cannot be represented as Decimal"),
    )))
}

#[cfg(feature = "rust_decimal")]
fn decimal_from_f32(value: f32) -> FromSqlResult<rust_decimal::Decimal> {
    rust_decimal::Decimal::from_f32(value).ok_or_else(|| invalid_decimal_float("FLOAT", value))
}

#[cfg(feature = "rust_decimal")]
fn decimal_from_f64(value: f64) -> FromSqlResult<rust_decimal::Decimal> {
    rust_decimal::Decimal::from_f64(value).ok_or_else(|| invalid_decimal_float("DOUBLE", value))
}

#[cfg(feature = "rust_decimal")]
impl FromSql for rust_decimal::Decimal {
    fn column_result(value: ValueRef<'_>) -> FromSqlResult<Self> {
        match value {
            ValueRef::Decimal(decimal) => decimal.try_into().map_err(|err| FromSqlError::Other(Box::new(err))),
            ValueRef::TinyInt(i) => rust_decimal::Decimal::from_i8(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::SmallInt(i) => rust_decimal::Decimal::from_i16(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::Int(i) => rust_decimal::Decimal::from_i32(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::BigInt(i) => rust_decimal::Decimal::from_i64(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::HugeInt(i) => rust_decimal::Decimal::from_i128(i).ok_or(FromSqlError::OutOfRange(i)),
            ValueRef::UHugeInt(i) => rust_decimal::Decimal::from_u128(i).ok_or(FromSqlError::OutOfRangeUnsigned(i)),
            ValueRef::UTinyInt(i) => rust_decimal::Decimal::from_u8(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::USmallInt(i) => rust_decimal::Decimal::from_u16(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::UInt(i) => rust_decimal::Decimal::from_u32(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::UBigInt(i) => rust_decimal::Decimal::from_u64(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::Float(f) => decimal_from_f32(f),
            ValueRef::Double(d) => decimal_from_f64(d),
            ValueRef::Timestamp(_, i) => rust_decimal::Decimal::from_i64(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::Date32(i) => rust_decimal::Decimal::from_i32(i).ok_or(FromSqlError::OutOfRange(i as i128)),
            ValueRef::Time64(TimeUnit::Microsecond, i) => {
                rust_decimal::Decimal::from_i64(i).ok_or(FromSqlError::OutOfRange(i as i128))
            }
            ValueRef::Text(_) => {
                let s = value.as_str()?;
                match s.parse::<rust_decimal::Decimal>() {
                    Ok(decimal) => Ok(decimal),
                    Err(_) => match s.parse::<i128>() {
                        Ok(i) => Err(FromSqlError::OutOfRange(i)),
                        Err(_) => Err(FromSqlError::InvalidType),
                    },
                }
            }
            _ => Err(FromSqlError::InvalidType),
        }
    }
}

#[cfg(test)]
mod test {
    use super::*;
    use crate::{Connection, Error, Result};

    #[test]
    fn decimal_new_accepts_valid_values() -> Result<()> {
        let decimal = Decimal::new(9, 2, 12345)?;

        assert_eq!(decimal.width(), 9);
        assert_eq!(decimal.scale(), 2);
        assert_eq!(decimal.value(), 12345);

        Ok(())
    }

    #[test]
    fn decimal_identity_ignores_width() {
        use std::collections::HashSet;

        let declared = Decimal::new(38, 0, 3).unwrap();
        let inferred = Decimal::new(1, 0, 3).unwrap();

        assert_eq!(declared.width(), 38);
        assert_eq!(inferred.width(), 1);
        assert_eq!(declared, inferred);
        assert_eq!(Value::Decimal(declared), Value::Decimal(inferred));

        let mut values = HashSet::new();
        values.insert(declared);
        values.insert(inferred);

        assert_eq!(values.len(), 1);
    }

    #[test]
    fn decimal_identity_keeps_scale() {
        use std::collections::HashSet;

        let integer = Decimal::new(2, 0, 10).unwrap();
        let fractional = Decimal::new(2, 1, 10).unwrap();

        assert_ne!(integer, fractional);

        let mut values = HashSet::new();
        values.insert(integer);
        values.insert(fractional);

        assert_eq!(values.len(), 2);
    }

    #[test]
    fn decimal_display_renders_scaled_value() {
        assert_eq!(Decimal::new(9, 2, 12345).unwrap().to_string(), "123.45");
        assert_eq!(Decimal::new(3, 3, 1).unwrap().to_string(), "0.001");
        assert_eq!(Decimal::new(4, 3, -1).unwrap().to_string(), "-0.001");
        assert_eq!(Decimal::new(3, 0, -123).unwrap().to_string(), "-123");
        assert_eq!(Decimal::new(5, 2, -12345).unwrap().to_string(), "-123.45");
        assert_eq!(Decimal::new(2, 2, 99).unwrap().to_string(), "0.99");
        assert_eq!(Decimal::new(1, 0, 0).unwrap().to_string(), "0");
        assert_eq!(format!("{:>10}", Decimal::new(9, 2, 12345).unwrap()), "    123.45");
        assert_eq!(format!("{:+}", Decimal::new(9, 2, 12345).unwrap()), "+123.45");
        assert_eq!(format!("{:08}", Decimal::new(9, 2, 12345).unwrap()), "00123.45");
    }

    #[test]
    fn decimal_new_rejects_invalid_values() {
        assert!(Decimal::new(3, 3, 1).is_ok());
        assert_eq!(
            Decimal::new(0, 0, 0).unwrap_err(),
            DecimalError::InvalidWidth {
                width: 0,
                max: Decimal::MAX_WIDTH,
            }
        );
        assert_eq!(
            Decimal::new(39, 0, 0).unwrap_err(),
            DecimalError::InvalidWidth {
                width: 39,
                max: Decimal::MAX_WIDTH,
            }
        );
        assert_eq!(
            Decimal::new(9, 10, 0).unwrap_err(),
            DecimalError::ScaleExceedsWidth { scale: 10, width: 9 }
        );
        assert_eq!(
            Decimal::new(2, 1, 100).unwrap_err(),
            DecimalError::ValueExceedsWidth { digits: 3, width: 2 }
        );
        assert_eq!(
            Decimal::new(38, 0, i128::MAX).unwrap_err(),
            DecimalError::ValueExceedsWidth { digits: 39, width: 38 }
        );
    }

    #[test]
    fn decimal_signed_scale_helper_validates_arrow_metadata() {
        assert_eq!(Decimal::validate_signed_scale(9, 2).unwrap(), 2);
        assert_eq!(
            Decimal::validate_signed_scale(9, -1).unwrap_err(),
            "negative decimal scale is not supported: -1"
        );
        assert_eq!(
            Decimal::validate_signed_scale(9, 10).unwrap_err(),
            "decimal scale 10 exceeds width 9"
        );
    }

